// Explicitly invoked review tool. It sends no telemetry and does not run model calls.
export function auditDesign(contract,root=document){
 const view=root.defaultView||window;const failures=[],observations=[];if(root.documentElement.dataset.appReady!=='true')failures.push({rule:'DS-app-not-ready'});const visible=el=>{if(!el||el.closest('[hidden]'))return false;const r=el.getBoundingClientRect(),s=view.getComputedStyle(el);return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden';};
 for(const [name,rule]of Object.entries(contract.surfaces))for(const surface of root.querySelectorAll(`[data-design-surface="${name}"]`)){if(!visible(surface))continue;const actions=new Map();for(const button of surface.querySelectorAll('button')){if(button.closest('[data-design-surface]')!==surface||!visible(button))continue;const action=button.dataset.designAction,r=button.getBoundingClientRect();if(!rule.actions.includes(action))failures.push({rule:'DS-action-family',surface:name,id:button.id,action:action||null});if(!contract.variants.includes(button.dataset.variant))failures.push({rule:'DS-component',surface:name,id:button.id});if(r.width<contract.targetSizeCssPx-.5||r.height<contract.targetSizeCssPx-.5)failures.push({rule:'DS-hit-target',surface:name,id:button.id,width:r.width,height:r.height});if(button.dataset.variant==='primary'&&!rule.primary.includes(action))failures.push({rule:'DS-primary-hierarchy',surface:name,id:button.id});actions.set(action,(actions.get(action)||0)+1);}
 for(const[action,count]of actions)if(count>1&&action!==rule.repeatedAction)failures.push({rule:'DS-duplicate-action',surface:name,action,count});observations.push({surface:name,actions:Object.fromEntries(actions)});}
 const strip=root.querySelector('#style-picker');if(visible(strip)){const widths=[...strip.querySelectorAll('button')].map(b=>b.getBoundingClientRect().width);if(widths.length&&strip.clientWidth<Math.min(...widths))failures.push({rule:'DS-clipped-chart-strip',width:strip.clientWidth});}
 for(const id of contract.forbiddenPersistentIds){const el=root.querySelector('#'+id);if(visible(el)&&!el.closest('#explore-tools,#voice-tools'))failures.push({rule:'DS-progressive-disclosure',id});}
 return {contractVersion:contract.version,viewport:{width:view.innerWidth,height:view.innerHeight},failures,observations,unverified:['taste and hierarchy judgment','task completion and recovery','actual touch gestures','graph target overlap','contrast and screen-reader behavior','real voice and model quality']};
}
